    #[allow(unused_mut)]
    pub fn from_json(entries: Vec<json_flat_parser::FlatJsonValue<&str>>, packetver: u32) -> Result<Self, String> {
        let mut packet = ServerAddr2::new(packetver);
        if let Some(entry) = entries.iter().find(|entry| entry.pointer.pointer.eq("/ip")) {
            if let Some(value) = entry.value {
                packet.set_ip(value.parse().map_err(|_| format!("Invalid value {} for ip", value))?);
            }
        }
        if let Some(entry) = entries.iter().find(|entry| entry.pointer.pointer.eq("/port")) {
            if let Some(value) = entry.value {
                packet.set_port(value.parse().map_err(|_| format!("Invalid value {} for port", value))?);
            }
        }
        if let Some(entry) = entries.iter().find(|entry| entry.pointer.pointer.eq("/name")) {
            if let Some(value) = entry.value {
                let mut char_value: [char; 20] = [0 as char; 20];
                for (i, c) in value.chars().enumerate() {
                    if i >= char_value.len() {
                        break;
                    }
                    char_value[i] = c;
                }
                packet.set_name(char_value);
            }
        }
        if let Some(entry) = entries.iter().find(|entry| entry.pointer.pointer.eq("/user_count")) {
            if let Some(value) = entry.value {
                packet.set_user_count(value.parse().map_err(|_| format!("Invalid value {} for user_count", value))?);
            }
        }
        if let Some(entry) = entries.iter().find(|entry| entry.pointer.pointer.eq("/state")) {
            if let Some(value) = entry.value {
                packet.set_state(value.parse().map_err(|_| format!("Invalid value {} for state", value))?);
            }
        }
        if let Some(entry) = entries.iter().find(|entry| entry.pointer.pointer.eq("/property")) {
            if let Some(value) = entry.value {
                packet.set_property(value.parse().map_err(|_| format!("Invalid value {} for property", value))?);
            }
        }
        if let Some(entry) = entries.iter().find(|entry| entry.pointer.pointer.eq("/unknown2")) {
            if let Some(value) = entry.value {
                let mut char_value: [char; 128] = [0 as char; 128];
                for (i, c) in value.chars().enumerate() {
                    if i >= char_value.len() {
                        break;
                    }
                    char_value[i] = c;
                }
                packet.set_unknown2(char_value);
            }
        }
        Ok(packet)
    }
    pub fn fill_raw(&mut self) {
      self.fill_raw_with_packetver(None)
    }
    pub fn fill_raw_with_packetver(&mut self, packetver: Option<u32>) {
    let mut wtr;
        wtr = vec![];
        wtr.write_u32::<LittleEndian>(self.ip).unwrap();
        self.ip_raw = wtr.try_into().unwrap();
        wtr = vec![];
        wtr.write_i16::<LittleEndian>(self.port).unwrap();
        self.port_raw = wtr.try_into().unwrap();
        wtr = vec![];
        for item in self.name {
            wtr.write_u8(item as u8 ).unwrap();
        }
        self.name_raw = wtr.try_into().unwrap();
        wtr = vec![];
        wtr.write_u16::<LittleEndian>(self.user_count).unwrap();
        self.user_count_raw = wtr.try_into().unwrap();
        wtr = vec![];
        wtr.write_u16::<LittleEndian>(self.state).unwrap();
        self.state_raw = wtr.try_into().unwrap();
        wtr = vec![];
        wtr.write_u16::<LittleEndian>(self.property).unwrap();
        self.property_raw = wtr.try_into().unwrap();
        wtr = vec![];
        for item in self.unknown2 {
            wtr.write_u8(item as u8 ).unwrap();
        }
        self.unknown2_raw = wtr.try_into().unwrap();

        wtr = vec![];
        wtr.append(&mut self.ip_raw.to_vec());
        wtr.append(&mut self.port_raw.to_vec());
        wtr.append(&mut self.name_raw.to_vec());
        wtr.append(&mut self.user_count_raw.to_vec());
        wtr.append(&mut self.state_raw.to_vec());
        wtr.append(&mut self.property_raw.to_vec());
        wtr.append(&mut self.unknown2_raw.to_vec());
        self.raw = wtr;
    }
